<style>
.pp-ui{--ink:#17324d;--muted:#71879a;--line:#e2ebf2;background:#f4f8fb;min-height:calc(100vh - 90px);padding:24px}.pp-hero{padding:25px 28px;border-radius:22px;background:linear-gradient(135deg,#123d60,#1d79aa);color:#fff;box-shadow:0 15px 32px rgba(20,65,98,.18)}.pp-hero h1{margin:0;color:#fff;font-weight:800;font-size:1.55rem}.pp-hero p{margin:7px 0 0;color:#dcecf6}.pp-card{border:1px solid var(--line);border-radius:18px;background:#fff;box-shadow:0 7px 20px rgba(34,70,96,.05)}.pp-group{overflow:hidden}.pp-group-head{padding:17px 20px;background:#f7fafc;border-bottom:1px solid var(--line)}.pp-group-title{color:var(--ink);font-weight:800}.pp-group-meta{font-size:.75rem;color:var(--muted)}.pp-page{padding:16px 20px;border-bottom:1px solid #edf2f6}.pp-page:last-child{border-bottom:0}.pp-page-name{font-weight:800;color:#1a557f}.pp-page-link{font-size:.74rem;color:#8497a5}.pp-actions{display:flex;flex-wrap:wrap;gap:6px;margin-top:9px}.pp-actions label{display:inline-flex;align-items:center;gap:5px;border:1px solid #d7e4ec;border-radius:999px;padding:5px 9px;background:#fff;color:#476277;font-size:.72rem;font-weight:700;cursor:pointer}.pp-actions input{accent-color:#1769aa}.pp-toolbar{padding:17px 20px}.pp-ui .btn{border-radius:10px;font-weight:700}.pp-ui .form-control,.pp-ui .form-select{border-radius:10px;border-color:#d6e3eb}.pp-ui .form-label{font-size:.73rem;text-transform:uppercase;letter-spacing:.04em;color:#587287;font-weight:800}.pp-chip{display:inline-flex;gap:5px;align-items:center;background:#e8f3fa;color:#1c6a98;border-radius:999px;padding:5px 9px;font-size:.7rem;font-weight:800}.pp-empty{text-align:center;padding:34px;color:var(--muted)}.pp-ui .modal-content{border:0;border-radius:18px;overflow:hidden}.pp-ui .modal-header{background:#f6f9fb;border-bottom:1px solid var(--line)}@media(max-width:700px){.pp-ui{padding:10px}.pp-hero{padding:21px}.pp-hero h1{font-size:1.3rem}.pp-page{padding:14px}.pp-toolbar{padding:14px}}
